:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --snake: #4ecca3;
  --food: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.1rem;
  font-weight: 600;
  background: var(--accent);
  padding: 6px 14px;
  border-radius: 8px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #0d0d1a;
  border-radius: 12px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(13, 13, 26, 0.88);
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px;
  text-align: center;
  transition: opacity 0.2s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.4rem;
  color: var(--primary);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
}

.btn {
  background: var(--accent);
  color: var(--text);
  border: 2px solid transparent;
  padding: 12px 24px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  font-family: inherit;
  min-width: 120px;
}

.btn:hover {
  background: #1a4a7a;
  border-color: var(--primary);
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: #0a2a4a;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #ff5a7a;
}

.btn.primary:active {
  background: #c73050;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.hint {
  text-align: center;
  font-size: 0.9rem;
  color: #888;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.2rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 100px;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayBtn = document.getElementById('overlayBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, dir, nextDir, food, score, state;
  let gameLoop = null;

  function resetGame() {
    snake = [{x: 10, y: 10}, {x: 9, y: 10}, {x: 8, y: 10}];
    dir = {x: 1, y: 0};
    nextDir = {x: 1, y: 0};
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = {x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID)};
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = '#0d0d1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // grid lines (subtle)
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    // food
    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    // snake
    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3a9e7a';
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    dir = nextDir;
    const head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      gameOver();
      return;
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function startLoop() {
    stopLoop();
    gameLoop = setInterval(step, 150);
  }

  function stopLoop() {
    if (gameLoop) {
      clearInterval(gameLoop);
      gameLoop = null;
    }
  }

  function setState(newState) {
    state = newState;
    if (state === 'playing') {
      overlay.classList.add('hidden');
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
      startLoop();
    } else if (state === 'paused') {
      stopLoop();
      overlayTitle.textContent = 'Paused';
      overlayText.innerHTML = 'Press Space or click Resume to continue.';
      overlayBtn.textContent = 'Resume';
      overlay.classList.remove('hidden');
      pauseBtn.textContent = 'Resume';
      pauseBtn.setAttribute('aria-label', 'Resume game');
    } else if (state === 'gameover') {
      stopLoop();
      overlayTitle.textContent = 'Game Over';
      overlayText.innerHTML = 'Final score: <strong>' + score + '</strong><br>Press Restart or click below to play again.';
      overlayBtn.textContent = 'Play Again';
      overlay.classList.remove('hidden');
      pauseBtn.textContent = 'Pause';
      pauseBtn.disabled = true;
    } else if (state === 'ready') {
      stopLoop();
      overlayTitle.textContent = 'How to Play';
      overlayText.innerHTML = 'Use arrow keys to move.<br>Press Space or click Start to begin.';
      overlayBtn.textContent = 'Start Game';
      overlay.classList.remove('hidden');
      pauseBtn.textContent = 'Pause';
      pauseBtn.disabled = false;
    }
  }

  function gameOver() {
    setState('gameover');
  }

  function restart() {
    stopLoop();
    resetGame();
    pauseBtn.disabled = false;
    setState('ready');
  }

  function togglePause() {
    if (state === 'playing') {
      setState('paused');
    } else if (state === 'paused') {
      setState('playing');
    }
  }

  function handleOverlayAction() {
    if (state === 'ready' || state === 'gameover') {
      resetGame();
      setState('playing');
    } else if (state === 'paused') {
      setState('playing');
    }
  }

  document.addEventListener('keydown', function(e) {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
      e.preventDefault();
    }

    if (key === ' ') {
      if (state === 'ready' || state === 'gameover') {
        handleOverlayAction();
      } else {
        togglePause();
      }
      return;
    }

    if (state !== 'playing') return;

    if (key === 'ArrowUp' && dir.y !== 1) nextDir = {x: 0, y: -1};
    else if (key === 'ArrowDown' && dir.y !== -1) nextDir = {x: 0, y: 1};
    else if (key === 'ArrowLeft' && dir.x !== 1) nextDir = {x: -1, y: 0};
    else if (key === 'ArrowRight' && dir.x !== -1) nextDir = {x: 1, y: 0};
  });

  overlayBtn.addEventListener('click', handleOverlayAction);
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  // Initialize: start paused with tutorial
  resetGame();
  setState('ready');
})();
